//! 重型任务串行协调。终止回执由工作线程退出时发出，页面切换不改变任务。
use crate::*;
use std::sync::OnceLock;
#[derive(Default)]struct Coordinator{active:Option<Value>,pending:Option<(String,Value,bool,u64)>,last:Option<Value>}
fn coordinator()->&'static Mutex<Coordinator>{static C:OnceLock<Mutex<Coordinator>>=OnceLock::new();C.get_or_init(Default::default)}
static SEQUENCE:AtomicU64=AtomicU64::new(1);
pub struct Guard{id:u64,proxy:EventLoopProxy<UiEvent>}
fn module(request:&Value)->&str{match request["cmd"].as_str().unwrap_or(""){"space_start"=>"space","smart_clean"|"goal_analyze"|"space_goal_save"=>"smart",_=>request["module"].as_str().unwrap_or("smart")}}
fn send(proxy:&EventLoopProxy<UiEvent>,value:Value){let _=proxy.send_event(UiEvent::Output(value));}
pub fn begin(request:&Value,proxy:&EventLoopProxy<UiEvent>)->Result<Guard,Value>{let mut c=coordinator().lock().unwrap();if let Some(active)=c.active.clone(){let token=format!("switch-{}",SEQUENCE.fetch_add(1,Ordering::SeqCst));c.pending=Some((token.clone(),request.clone(),false,active["job_id"].as_u64().unwrap()));return Err(json!({"event":"task_conflict","active":active,"next_module":module(request),"switch_id":token,"request_id":request["request_id"]}))}let id=SEQUENCE.fetch_add(1,Ordering::SeqCst);let info=json!({"job_id":id,"module":module(request),"phase":"starting","running":true,"cancelable":true,"stop_requested":false,"stop_acknowledged":false,"request_id":request["request_id"],"progress":0});c.active=Some(info.clone());drop(c);send(proxy,json!({"event":"task_status","active":info}));Ok(Guard{id,proxy:proxy.clone()})}
pub fn status(proxy:&EventLoopProxy<UiEvent>){let c=coordinator().lock().unwrap();send(proxy,json!({"event":"task_status","active":c.active,"last":c.last,"pending":c.pending.as_ref().map(|p|json!({"switch_id":p.0,"next_module":module(&p.1),"job_id":p.3}))}));}
pub fn stop_requested(module:&str){let mut c=coordinator().lock().unwrap();if let Some(a)=c.active.as_mut(){if a["module"]==module{a["stop_requested"]=json!(true)}}}
pub fn switch(request:&Value,proxy:&EventLoopProxy<UiEvent>){let mut c=coordinator().lock().unwrap();let Some((token,_,_,original_job))=c.pending.as_ref()else{drop(c);message(proxy,"待切换任务已结束，请重新开始扫描。",true);return};if request["switch_id"]!=*token||c.active.as_ref().is_some_and(|a|a["job_id"]!=*original_job){drop(c);message(proxy,"此切换请求已失效，请重新开始扫描。",true);return}if request["confirm"]!=true{c.pending=None;drop(c);status(proxy);return}if let Some(a)=c.active.as_mut(){let module=a["module"].as_str().unwrap_or("smart").to_owned();a["stop_requested"]=json!(true);c.pending.as_mut().unwrap().2=true;drop(c);let _=proxy.send_event(UiEvent::Request(json!({"cmd":"cancel","module":module})));status(proxy)}else{let (_,next,_,_)=c.pending.take().unwrap();drop(c);let _=proxy.send_event(UiEvent::Request(next));}}
pub fn observe(value:&Value){let mut c=coordinator().lock().unwrap();let Some(a)=c.active.as_mut()else{return};let event=value["event"].as_str().unwrap_or("");if !["progress","scan_partial","large_partial","space_view","smart_clean","goal_analysis"].contains(&event){return}let m=if event=="space_view"{"space"}else if ["smart_clean","goal_analysis"].contains(&event){"smart"}else{value["module"].as_str().unwrap_or("")};if a["module"]!=m{return}a["phase"]=value.get("phase").cloned().unwrap_or(json!("scan"));a["progress"]=value.get("processed").or_else(||value.get("scanned")).or_else(||value.get("data").and_then(|d|d.get("scanned"))).cloned().unwrap_or(json!(0));a["total"]=value["total"].clone();}
impl Drop for Guard{fn drop(&mut self){let mut c=coordinator().lock().unwrap();if c.active.as_ref().is_none_or(|a|a["job_id"]!=self.id){return}let mut ended=c.active.take().unwrap();ended["running"]=json!(false);ended["cancelable"]=json!(false);ended["stop_acknowledged"]=ended["stop_requested"].clone();ended["phase"]=json!(if ended["stop_requested"]==true{"stopped"}else{"finished"});c.last=Some(ended.clone());let next=if c.pending.as_ref().is_some_and(|p|p.2&&p.3==self.id){c.pending.take().map(|p|p.1)}else{None};drop(c);send(&self.proxy,json!({"event":"task_status","active":null,"last":ended}));if let Some(next)=next{let _=self.proxy.send_event(UiEvent::Request(next));}}}
